import React, { useState, useEffect, useCallback } from 'react';
import styles from './Navbar.module.css';

const NAV_LINKS = [
  { label: 'Accueil', href: '#hero' },
  { label: 'Services', href: '#services' },
  { label: 'À propos', href: '#about' },
  { label: 'Résultats', href: '#results' },
  { label: 'Contact', href: '#contact' },
];

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  const handleScroll = useCallback(() => {
    setScrolled(window.scrollY > 60);
  }, []);

  useEffect(() => {
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  const closeMenu = useCallback(() => setMenuOpen(false), []);

  return (
    <nav className={`${styles.nav} ${scrolled ? styles.scrolled : ''}`}>
      <a href="#hero" className={styles.logo}>
        <span className={styles.logoIcon}>
          <svg width="32" height="32" viewBox="0 0 100 100" fill="none">
            <defs>
              <linearGradient id="lg1" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stopColor="#38d2ff"/>
                <stop offset="50%" stopColor="#7c5cfc"/>
                <stop offset="100%" stopColor="#e040fb"/>
              </linearGradient>
            </defs>
            <rect x="8" y="20" width="12" height="60" rx="4" fill="url(#lg1)"/>
            <path d="M20 20 Q80 20 80 50 Q80 80 20 80" stroke="url(#lg1)" strokeWidth="12" fill="none" strokeLinecap="round"/>
            <circle cx="10" cy="10" r="5" fill="#38d2ff" opacity="0.8"/>
            <circle cx="25" cy="5" r="4" fill="#38d2ff" opacity="0.6"/>
            <circle cx="38" cy="10" r="3" fill="#7c5cfc" opacity="0.7"/>
          </svg>
        </span>
        <span className={styles.logoText}>Digitalink</span>
      </a>

      <ul className={`${styles.links} ${menuOpen ? styles.open : ''}`}>
        {NAV_LINKS.map(l => (
          <li key={l.href}>
            <a href={l.href} className={styles.link} onClick={closeMenu}>{l.label}</a>
          </li>
        ))}
        <li>
          <a href="#contact" className={styles.cta} onClick={closeMenu}>Démarrer un projet</a>
        </li>
      </ul>

      <button className={styles.burger} onClick={() => setMenuOpen(o => !o)} aria-label="Toggle menu">
        <span className={menuOpen ? styles.barOpen : ''}/>
        <span className={menuOpen ? styles.barHide : ''}/>
        <span className={menuOpen ? styles.barOpen2 : ''}/>
      </button>
    </nav>
  );
}
